package pe.ganadoconecta.modulos.sanidad.adaptadores.entrada.http;
import java.time.*;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.util.MultiValueMap;import org.springframework.web.bind.annotation.*;
import pe.ganadoconecta.modulos.identidad.adaptadores.entrada.http.IdentidadAutenticada;import pe.ganadoconecta.modulos.sanidad.aplicacion.*;import pe.ganadoconecta.modulos.sanidad.dominio.*;
@RestController @RequestMapping("/api/v1/ganaderias/{ganaderiaId}/agenda-sanitaria") @Profile("postgres")
public class AgendaSanitariaControlador{
 private final ProgramarActividadSanitaria programar;private final ConsultarAgendaSanitaria consultar;private final CompletarActividadSanitaria completar;private final Clock reloj;
 public AgendaSanitariaControlador(ProgramarActividadSanitaria p,ConsultarAgendaSanitaria c,CompletarActividadSanitaria x,Clock r){programar=p;consultar=c;completar=x;reloj=r;}
 @PostMapping ResponseEntity<Respuesta> crear(@PathVariable UUID ganaderiaId,@RequestBody Solicitud b,@RequestParam MultiValueMap<String,String> q,@AuthenticationPrincipal IdentidadAutenticada i){sinParametros(q);var a=programar.ejecutar(i.usuarioId(),i.sesionId(),ganaderiaId,b.animalId,b.actividadId,b.eventoOrigenId,tipo(b.tipo),b.fechaPrevista,b.descripcion,b.observaciones);return ResponseEntity.status(201).cacheControl(CacheControl.noStore()).body(respuesta(a));}
 @GetMapping ResponseEntity<List<Respuesta>> listar(@PathVariable UUID ganaderiaId,@RequestParam(required=false) UUID animalId,@RequestParam(required=false) String tipo,@RequestParam(required=false) String estado,@RequestParam MultiValueMap<String,String> q,@AuthenticationPrincipal IdentidadAutenticada i){if(!Set.of("animalId","tipo","estado").containsAll(q.keySet())||q.values().stream().anyMatch(v->v.size()!=1))throw new SolicitudSanitariaInvalidaException();var r=consultar.ejecutar(i.usuarioId(),ganaderiaId,animalId,tipo==null?null:tipo(tipo),estado==null?null:estado(estado));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(r.stream().map(this::respuesta).toList());}
 @PostMapping("/{actividadId}/completar") ResponseEntity<Respuesta> completar(@PathVariable UUID ganaderiaId,@PathVariable UUID actividadId,@RequestParam MultiValueMap<String,String> q,@AuthenticationPrincipal IdentidadAutenticada i){sinParametros(q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(respuesta(completar.ejecutar(i.usuarioId(),i.sesionId(),ganaderiaId,actividadId)));}
 private Respuesta respuesta(ActividadSanitaria a){LocalDate hoy=reloj.instant().atZone(ZoneId.of("America/Lima")).toLocalDate();return new Respuesta(a.id(),a.animalId(),a.eventoOrigenId(),a.tipo().name(),a.fechaPrevista(),a.descripcion(),a.observaciones(),a.estado().name(),a.estadoVisible(hoy),a.version(),a.creadoEn(),a.completadoEn());}
 private static void sinParametros(MultiValueMap<String,String> q){if(!q.isEmpty())throw new SolicitudSanitariaInvalidaException();}
 private static TipoActividadSanitaria tipo(String v){try{return TipoActividadSanitaria.valueOf(v);}catch(Exception e){throw new DatoSanitarioInvalidoException("tipo");}}
 private static EstadoActividadSanitaria estado(String v){try{return EstadoActividadSanitaria.valueOf(v);}catch(Exception e){throw new DatoSanitarioInvalidoException("estado");}}
 record Solicitud(UUID actividadId,UUID animalId,UUID eventoOrigenId,String tipo,LocalDate fechaPrevista,String descripcion,String observaciones){@Override public String toString(){return "Solicitud[datos=PROTEGIDOS]";}}
 record Respuesta(UUID actividadId,UUID animalId,UUID eventoOrigenId,String tipo,LocalDate fechaPrevista,String descripcion,String observaciones,String estado,String estadoVisible,long version,Instant creadoEn,Instant completadoEn){}
}
